<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Classify/user_operate_list',array('type'=>1))}" <eq name='type' value='1'>class='on'</eq> >置顶记录</a>					<a href="{pigcms{:U('Classify/user_operate_list',array('type'=>2))}" <eq name='type' value='2'>class='on'</eq> >发红包记录</a>					<a href="{pigcms{:U('Classify/user_operate_list',array('type'=>3))}" <eq name='type' value='3'>class='on'</eq> >刷新记录</a>					<a href="{pigcms{:U('Classify/user_operate_list',array('type'=>4))}" <eq name='type' value='4'>class='on'</eq> >发布时打赏</a>					<a href="{pigcms{:U('Classify/user_operate_list',array('type'=>5))}" <eq name='type' value='5'>class='on'</eq> >打赏后查看</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="/admin.php?g=System&c=Classify&a=user_operate_list" method="get">							<input type="hidden" value="Classify" name="c"></input>							<input type="hidden" value="user_operate_list" name="a"></input>							<input type="hidden" value="{pigcms{$_GET.type|default=1}" name="type"></input>							<select name='search_type'>								<option value="phone" <eq name="_GET.search_type" value='phone'>selected='selected'</eq> >手机号</option>								<option value="nickname" <eq name="_GET.search_type" value='nickname'>selected='selected'</eq>>昵 称</option>							</select>							<span>								<input type="text" value="{pigcms{$_GET.keyword}" name="keyword" style="height: 22px;width: 160px;text-indent:5px;" placeholder='请输入搜索关键字' />							</span>&nbsp;&nbsp;&nbsp;							<span>								时间：								<input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>			   								<input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>							</span>&nbsp;&nbsp;&nbsp;							<input type="submit" value="查询" class="button"/>							<span style="float: left;margin-right: 100px;">总消费：{pigcms{$config['Currency_symbol']}{pigcms{$total_money|default=0}</span>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<if condition="empty($_GET['cat_fid'])">								<col/>								<col/>								<col/>							</if>							<col/>						</colgroup>						<thead>							<tr>								<th style="width:10%;">编号</th>								<th style="width:20%">用户信息</th>								<th style="width:10%;">金额</th>								<th>描述</th>								<th style="width:15%;">操作时间</th>							</tr>						</thead>						<tbody>							<if condition="is_array($money_list)">								<volist name="money_list" id="vo">									<tr>										<td>{pigcms{$vo.pigcms_id}</td>										<td style="line-height:22px;padding:5px 0;">											用户id：{pigcms{$vo.uid}<br/>											昵称：{pigcms{$vo.nickname}<br/>											手机号：{pigcms{$vo.phone}<br/>										</td>										<td>{pigcms{$vo.money}</td>										<td>{pigcms{$vo.desc}</td>										<td>{pigcms{$vo.date}</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="9">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>